/* 连续创作壳：复用阶段内容，作品位置与未保存编辑独立于媒体数据。 */
(()=>{
 const C=Cimora,{S,M,E,link}=C;createCimoraNavigationModel(M,S);const N=M.navigation;
 const B=(t,a,extra='')=>`<button type="button" class="cm-button ghost" data-nav="${a}" ${extra}>${t}</button>`;
 const creation=()=>['create','canvas'].includes(S.context.parts[1]);
 function phaseURL(c,key,view='flow'){return N.imported(c)?N.url(c,'boards','flow','&import='+key):N.url(c,key,view);}
 function next(c){const key=N.current(c,S.context.params);if(N.imported(c)&&key==='review'){const eps=N.adaptations(c);return eps.length?[N.handoff(c,eps[0]),'下一步：检查已有动画来源差异']:[null,'下一步：创建动画改编…'];}if(c.c.kind==='episode'&&key==='boards'){const s=M.production.shots(c.e).find(s=>M.adaptation.differences(c,s).length);if(s)return [N.url(c,'boards','flow','&shot='+s.id+'&compare=1'),'下一步：比较来源变化'];}const steps=N.stages(c),i=steps.findIndex(x=>x[0]===key);if(i>=0&&i<steps.length-1)return [phaseURL(c,steps[i+1][0]),'下一步：'+steps[i+1][1]];if(c.c.kind==='episode'&&key==='story')return [N.url(c,'boards','flow'),'下一步：确认镜头方案'];return ['/app/projects/'+c.p.id,'返回项目，接续其他作品'];}
 function header(c){const key=N.current(c,S.context.params),[to,label]=next(c),ss=N.stages(c);return `<section class="nv-work-context"><div class="nv-work-heading"><div>${link(E(c.p.name),'/app/projects/'+c.p.id,'cm-text-link')}<h1>${c.c.kind==='episode'?'动画集':'漫画章'} · ${E(c.c.title)}</h1><p>${E(N.status(c))}</p></div><div class="nv-views" aria-label="作品视图">${B('流程','view','data-view="flow" '+(c.e.view==='flow'?'aria-current="true"':''))}${!N.imported(c)?B('画布','view','data-view="canvas" '+(c.e.view==='canvas'?'aria-current="true"':'')):''}</div></div><nav class="nv-stage-nav" aria-label="作品阶段">${ss.map(([k,t],i)=>link(`<small>${i+1}</small>${t}`,phaseURL(c,k,c.e.view),k===key?'active':'')).join('')}</nav><div class="nv-current-task"><span><b>当前任务：</b>${E(N.task(c))}</span>${to?link(label,to,'cm-button primary'):B(label,'new-adaptation')}${c.c.kind==='episode'?link('编辑本集内容',N.url(c,'story','flow'),'cm-text-link'):!N.imported(c)&&key==='story'?link('角色与场景草案',N.url(c,'assets','flow'),'cm-text-link'):''}</div></section>`;}
 const oldStudio=C.studio;C.studio=c=>{N.remember(c,S.context.params);let html=oldStudio(c);const doc=new DOMParser().parseFromString(html,'text/html');doc.querySelectorAll('.cm-creation-header,.cm-chapter-strip,.cm-step-nav,.bc-flow-return,.ad-chapter-tools,.ed-header,.im-workbench>header,.im-workbench>nav,.cm-project-note').forEach(el=>el.remove());const bc=doc.querySelector('.bc-toolbar');if(bc)bc.querySelectorAll('[data-board="flow"],a[href*="stage=audio"]').forEach(el=>el.remove());const di=doc.querySelector('.di-flow');if(di){const details=doc.createElement('details');details.className='nv-local-tools';details.innerHTML='<summary>本镜局部操作</summary>';di.before(details);details.append(di);}return header(c)+`<div class="nv-stage-body">${doc.body.innerHTML}</div>`;};
 function work(c){return `<article class="cm-panel nv-work-card"><div><small>${c.c.kind==='episode'?'动画集':N.imported(c)?'上传漫画 · 来源准备':'漫画章'}</small><h3>${E(c.c.title)}</h3><p>${E(N.status(c))}</p><p>继续任务：${E(N.task(c))}</p></div>${link('继续此作品 →',N.resume(c),'cm-button primary')}</article>`;}
 const oldProject=C.project;C.project=p=>{if(!p)return oldProject(p);const c=M.resume(p);M.activate(p.id,c.c.id);return `<section class="nv-project"><div class="cm-page-heading"><div><small>当前项目</small><h1>${E(p.name)}</h1><p>${E(p.desc||'故事、漫画章与动画集分别保存。')}</p></div>${link('继续创作：'+E(N.task(c)),N.resume(c),'cm-button primary')}</div><h2>故事与漫画章节</h2>${p.chapters.map(ch=>work(M.context(p.id,ch.id))).join('')||'<p>本项目从动画直接开始，无需先制作漫画。</p>'}<h2>动画剧集</h2>${(p.episodes||[]).map(ep=>work(M.context(p.id,ep.id))).join('')||'<p>还没有动画；可从漫画交接，也可独立创作。</p>'}<div class="cm-inline-actions"><button class="cm-button ghost" data-prod="chapter">＋ 添加漫画章</button><button class="cm-button ghost" data-prod="new-episode">＋ 独立新建动画集</button></div></section>`;};
 function continueCards(){for(const card of S.$$('.hm-resume-card,.cm-project-card')){const a=card.querySelector('a[href*="/app/create/"],a[href*="/app/projects/"]');if(!a)continue;const pid=a.getAttribute('href').split('/')[3]?.split('?')[0],p=S.project(pid);if(!p)continue;const c=M.resume(p),url='#'+N.resume(c);card.querySelectorAll('a[href*="/app/create/"]').forEach(a=>a.href=url);if(card.matches('.hm-resume-card')){card.querySelectorAll('.hm-resume-art,h3 a').forEach(a=>a.href=url);const text=card.querySelector('h3+p');if(text)text.textContent=c.c.title+' · '+N.task(c);const progress=card.querySelector('.hm-project-progress');if(progress)progress.remove();const small=card.querySelector('footer small');if(small)small.textContent=N.status(c);}else{const foot=card.querySelector('footer span');if(foot)foot.textContent=N.task(c);}}}
 function handoffUI(c){const eps=N.adaptations(c);return `<section class="cm-panel nv-handoff"><h3>${eps.length?'接续已有动画':'漫画交接到动画'}</h3><p>${eps.length?'漫画变化先到已有动画逐镜比较；旧候选、采用与冻结继续保留。':'创建独立动画，漫画原作继续保留。'}</p>${eps.map(ep=>link('继续 '+E(ep.title)+' · 检查来源差异',N.handoff(c,ep),'cm-button primary')).join('')}${B(eps.length?'另外创建新改编…':'创建动画改编…','new-adaptation')}</section>`;}
 const oldAfter=C.afterRender;C.afterRender=r=>{oldAfter(r);if(creation()){const c=C.ctx();if(c){N.remember(c,r.params);if(c.c.kind!=='episode'&&(!N.imported(c)||r.params.get('import')==='review'))S.$('.nv-stage-body')?.insertAdjacentHTML('beforeend',handoffUI(c));const title=S.$('.cm-breadcrumb strong');if(title)title.textContent=c.p.name+' / '+c.c.title;S.$$('.pd-directory a[href*="/app/create/"]').forEach(a=>{const parts=a.getAttribute('href').slice(1).split('?')[0].split('/'),unit=[...c.p.chapters,...(c.p.episodes||[])].find(x=>x.id===parts[4]);if(unit&&!a.closest('details:not([open])'))a.href='#'+N.resume(M.context(c.p.id,unit.id));});}}continueCards();const cc=C.ctx();if(cc)S.$$('.pd-directory details[open]>a[href*="/app/create/"]').forEach(a=>{const id=a.getAttribute('href').slice(1).split('?')[0].split('/')[4],unit=[...cc.p.chapters,...(cc.p.episodes||[])].find(x=>x.id===id);if(unit)a.href='#'+N.resume(M.context(cc.p.id,id));});baseline();lastHash=location.hash;};
 // 所有改编创建入口先交接或确认，禁止一次普通点击静默复制作品。
 let pendingChapter=null;
 function newAdaptation(c){pendingChapter={project:c.p.id,unit:c.c.id};S.modal('创建另一部独立动画改编',`<p>来源：${E(c.c.title)}。确认后新增一部独立动画集，不覆盖已有动画；取消不会新增。</p>`,B('取消，不新建','cancel-adaptation')+B('确认新建独立改编','confirm-adaptation'));}
 function handoff(c){const eps=N.adaptations(c);if(eps.length===1){S.route(N.handoff(c,eps[0]));return;}if(eps.length){S.modal('选择已有动画接续',handoffUI(c),B('返回当前作品','cancel-adaptation'));return;}if(N.imported(c)){S.route(phaseURL(c,'review'));return;}newAdaptation(c);}
 window.addEventListener('click',ev=>{if(ev.target.closest('#nv-leave')||dirty.size&&!bypass)return;const el=ev.target.closest('[data-nav]');if(el){ev.preventDefault();ev.stopImmediatePropagation();const c=C.ctx();switch(el.dataset.nav){case'view':{const view=el.dataset.view;if(view==='canvas'){if(c.e.editing&&['audio','review'].includes(c.e.stage)){const x=c.e.editing.clips.find(x=>x.id===c.e.editing.selectedId);if(x)c.e.selectedShotId=x.shotId;}if(c.c.kind==='episode'&&c.e.selectedShotId){const ss=M.production.shots(c.e),i=ss.findIndex(s=>s.id===c.e.selectedShotId);c.e.creationCanvas??={viewport:{x:20,y:20,zoom:.65},positions:{},branches:{}};Object.assign(c.e.creationCanvas,{selected:'shot:'+c.e.selectedShotId,group:Math.max(0,Math.floor(i/6)),panel:true});}}if(c.c.kind!=='episode'){const pid=c.e.creationCanvas?.selected?.startsWith('panel:')?c.e.creationCanvas.selected.slice(6):c.e.navigation?.panelId;if(pid&&c.e.boards.some(b=>b.id===pid)){if(view==='canvas'){c.e.creationCanvas??={viewport:{x:20,y:20,zoom:.65},positions:{},branches:{}};Object.assign(c.e.creationCanvas,{selected:'panel:'+pid,group:Math.floor(c.e.boards.findIndex(b=>b.id===pid)/6),panel:true});}S.route(N.url(c,c.e.stage,view,'&panel='+pid));return;}}S.route(N.url(c,c.e.stage,view));return;}case'new-adaptation':newAdaptation(c);return;case'cancel-adaptation':pendingChapter=null;S.close();return;case'confirm-adaptation':{const from=pendingChapter&&M.context(pendingChapter.project,pendingChapter.unit);if(!from)return;let cc;if(N.imported(from)){const r=M.imports.adapt(from);if(r.error){S.toast(r.error);return;}cc=r.context;}else{if(from.e.run&&['running','paused'].includes(from.e.run.status)){S.toast('请先停止当前制作批次');return;}const ep=M.production.addEpisode(from.p,from.c.title+' · 动画改编',[from.c.id]);cc=M.activate(from.p.id,ep.id);}pendingChapter=null;S.route(N.url(cc,'boards','flow'));return;}}}
 const legacy=ev.target.closest('[data-adapt="adapt"],[data-cm="enable-motion"],[data-import="adapt"]');if(legacy){ev.preventDefault();ev.stopImmediatePropagation();handoff(C.ctx());}},true);

 // 未保存表单保留原DOM，保护对话框独立于原编辑弹窗。
 const forms='form[data-direct-form],form[data-edit-form],form[data-import-form],form[data-comic-form],form[data-adapt-form],form[data-prod-form],form[data-cm-form]';
 const dirty=new Map(),initial=new WeakMap();let lastHash=location.hash,pendingLeave=null,bypass=false,saving=false,savedLabel='已保存到本机';
 const oldRender=S.render;S.render=(...args)=>{if(saving||[...dirty.values()].some(d=>d.node.isConnected))return;return oldRender(...args);};
 const values=f=>JSON.stringify([...f.elements].filter(e=>e.name&&e.type!=='file').map(e=>[e.name,e.value,e.checked]));
 function baseline(){savedLabel=S.$('.cm-saved')?.textContent||savedLabel;for(const f of S.$$(forms))if(!initial.has(f))initial.set(f,values(f));for(const [key,d]of dirty)if(!d.node.isConnected)dirty.delete(key);}
 function scriptField(el){return el.matches('#cm-story-text,[data-adapt-input="script"]');}
 window.addEventListener('focusin',ev=>{const f=ev.target.closest(forms);if(f&&!initial.has(f))initial.set(f,values(f));},true);
 window.addEventListener('input',ev=>{const el=ev.target;if(!creation())return;const f=el.closest(forms);if(f){if(values(f)===initial.get(f))dirty.delete(f);else dirty.set(f,{node:f,type:'form'});}else if(scriptField(el)){const c=C.ctx();if(el.value===c.e.script)dirty.delete(el);else dirty.set(el,{node:el,type:'script',c});}S.$('.cm-saved')?.replaceChildren(document.createTextNode(dirty.size?'有未保存编辑':savedLabel));},true);
 window.addEventListener('change',ev=>{const el=ev.target;if(el.matches('[data-prod-change=project],[data-prod-change=unit],[data-cm-change=scope-project],[data-cm-change=scope-chapter]')&&dirty.size&&!bypass){ev.preventDefault();ev.stopImmediatePropagation();const value=el.value,c=C.ctx();el.value=el.dataset.prodChange==='project'||el.dataset.cmChange==='scope-project'?c.p.id:c.c.id;leave(()=>{const selector=el.dataset.prodChange?'[data-prod-change="'+el.dataset.prodChange+'"]':'[data-cm-change="'+el.dataset.cmChange+'"]';const next=S.$(selector);if(next){next.value=value;next.dispatchEvent(new Event('change',{bubbles:true}));}});return;}const f=el.closest(forms);if(!f||!creation())return;if(values(f)===initial.get(f))dirty.delete(f);else dirty.set(f,{node:f,type:'form'});S.$('.cm-saved')?.replaceChildren(document.createTextNode(dirty.size?'有未保存编辑':savedLabel));},true);
 S.navigationScriptSaved=()=>{for(const [k,d]of dirty)if(d.type==='script')dirty.delete(k);if(!dirty.size)S.$('.cm-saved')?.replaceChildren(document.createTextNode(savedLabel));};
 S.navigationSaved=(f,success)=>{if(success){dirty.delete(f);initial.set(f,values(f));if(!dirty.size)S.$('.cm-saved')?.replaceChildren(document.createTextNode(savedLabel));}if(pendingLeave)pendingLeave.saveResult=success;};
 function discard(){for(const d of dirty.values()){if(d.type==='script'){delete d.c.e.scriptDraft;M.save();}}dirty.clear();}
 function leave(run){if(bypass||!dirty.size)return false;if(pendingLeave)return true;pendingLeave={run,focus:document.activeElement};const overlay=document.createElement('div');overlay.id='nv-leave';overlay.innerHTML=`<section role="dialog" aria-modal="true" aria-labelledby="nv-leave-title"><h2 id="nv-leave-title">还有未保存编辑</h2><p>保存后继续、放弃这次编辑，或留在当前作品。已有采用和交付不会被覆盖。</p><p class="nv-save-error" role="status"></p><div>${B('留在此处','stay')}${B('放弃编辑并继续','discard')}${B('保存并继续','save')}</div></section>`;document.body.append(overlay);overlay.querySelector('button').focus();return true;}
 function finish(run){const focus=pendingLeave?.focus;document.querySelector('#nv-leave')?.remove();pendingLeave=null;if(run){bypass=true;try{run();}finally{bypass=false;}}else focus?.focus();}
 S.beforeRoute=to=>!leave(()=>S.route(to));
 S.beforeHashChange=()=>{if(bypass||location.hash===lastHash||!dirty.size)return true;const target=location.hash;history.replaceState(null,'',lastHash);leave(()=>S.route(target.slice(1)));return false;};
 window.addEventListener('beforeunload',ev=>{if(dirty.size){ev.preventDefault();ev.returnValue='';}});
 window.addEventListener('keydown',ev=>{if(!pendingLeave){if(ev.key==='Escape'&&dirty.size&&!S.$('#site-modal').hidden){ev.preventDefault();ev.stopImmediatePropagation();leave(()=>S.close());}return;}if(ev.key==='Escape'){ev.preventDefault();ev.stopImmediatePropagation();finish();}if(ev.key==='Tab'){const bs=[...document.querySelectorAll('#nv-leave button')],i=bs.indexOf(document.activeElement);ev.preventDefault();bs[(i+(ev.shiftKey?-1:1)+bs.length)%bs.length].focus();}},true);
 window.addEventListener('click',ev=>{const choice=ev.target.closest('#nv-leave [data-nav]');if(choice){ev.preventDefault();ev.stopImmediatePropagation();const a=choice.dataset.nav;if(a==='stay'){finish();return;}if(a==='discard'){const run=pendingLeave.run;discard();finish(run);return;}if(a==='save'){saving=true;try{for(const d of [...dirty.values()]){if(d.type==='form'){if(!d.node.reportValidity()){S.$('#nv-leave .nv-save-error').textContent='请返回编辑，补齐有效内容后再保存。';return;}pendingLeave.saveResult=null;d.node.requestSubmit();if(pendingLeave?.saveResult!==true){S.$('#nv-leave .nv-save-error').textContent='尚未保存，请留在此处检查输入或使用表单保存按钮。';return;}}else{if(d.node.value.trim().length<5){S.$('#nv-leave .nv-save-error').textContent='请至少填写一句完整故事。';return;}d.c.e.script=d.node.value;delete d.c.e.scriptDraft;M.change(d.c.e,'story','保存故事新版本');M.save();dirty.delete(d.node);}}const run=pendingLeave.run;saving=false;S.render();finish(run);}finally{saving=false;}}return;}
 if(bypass||!dirty.size||pendingLeave)return;if(ev.target===S.$('#site-modal')){ev.preventDefault();ev.stopImmediatePropagation();leave(()=>S.close());return;}const target=ev.target.closest('a[href^="#"],button,[data-prod-change],[data-cm-change]');if(!target)return;const own=target.closest(forms);if(own&&dirty.has(own)&&target.type==='submit')return;if(target.closest('#nv-leave'))return;
 // 原位保存按钮不触发离开确认。
 if(target.matches('[data-adapt="save-script"],[data-cm="confirm-script"]')){return;}
 const href=target.getAttribute('href'),attrs=[...target.attributes].filter(a=>a.name.startsWith('data-')).map(a=>`[${a.name}="${CSS.escape(a.value)}"]`).join('');if(!href&&!attrs)return;
 ev.preventDefault();ev.stopImmediatePropagation();leave(()=>{if(href)S.route(href.slice(1));else{const replacement=document.querySelector(attrs);replacement?.click();}});
 },true);
 // 捕获阶段顺序：离开保护必须先于本模块的其他导航及旧模块监听器。
 // window监听按注册顺序执行；上面的业务导航在有脏编辑时先让给保护层。
 C.navigationGuard={dirty,leave};
})();
